def compute(vars):
    current_maturities = [vars["v1"], vars["v2"]]
    value = sum(current_maturities) / len(current_maturities)
    return {
        "value": value,
        "trace": {
            "current_maturities": current_maturities,
            "count": len(current_maturities),
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
